use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within bounds
        ensures
            result.len() == a.len(), // The output vector has the same length as the input
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i], // Elements are the same
    {
        let mut result: Vec<T> = Vec::new(); // Initialize the result vector
        let mut idx: nat = 0; // Initialize index

        while idx < a.len() as nat
            invariant
                idx <= a.len() as nat, // Index is within bounds
                result.len() == idx, // Result vector has the same number of elements as idx
                forall|j: nat| 0 <= j < idx ==> result[j] == a[j], // Elements in result match those in a
            decreases a.len() as nat - idx, // Decrease clause
        {
            result.push(a[idx as usize]); // Copy the element from input to result
            idx = idx + 1; // Increment index
        }

        result // Return the result vector
    }
}

